/**
 * Deliverable 9.7: Tolerant JSON Parser for 7B-9B Local LLMs.
 * Robustly parses and repairs malformed JSON generated by local models:
 * - Markdown fences (```json, ```)
 * - Trailing commas before } and ]
 * - Unquoted object keys
 * - Single quotes used instead of double quotes
 * - Truncated payloads with unbalanced brackets/braces and unclosed quotes
 */

export interface TolerantParseResult<T = any> {
  success: boolean;
  data?: T;
  wasRepaired: boolean;
  repairTechnique?: 'none' | 'fence_strip' | 'syntax_clean' | 'bracket_balance';
  originalText: string;
  repairedText?: string;
  error?: string;
}

export class TolerantJsonParser {
  /**
   * Attempts to parse JSON using multi-stage tolerant repair heuristics.
   */
  public static parse<T = any>(rawInput: string): TolerantParseResult<T> {
    if (!rawInput || typeof rawInput !== 'string') {
      return {
        success: false,
        wasRepaired: false,
        originalText: rawInput ?? '',
        error: 'Input is empty or not a string'
      };
    }

    const trimmed = rawInput.trim();

    // Stage 1: Fast direct JSON parse
    try {
      const data = JSON.parse(trimmed);
      return {
        success: true,
        data,
        wasRepaired: false,
        repairTechnique: 'none',
        originalText: rawInput
      };
    } catch {
      // Continue to repair pipeline
    }

    // Stage 2: Strip Markdown code fences and extract JSON candidate block
    let cleaned = this.stripMarkdownFences(trimmed);
    try {
      const data = JSON.parse(cleaned);
      return {
        success: true,
        data,
        wasRepaired: true,
        repairTechnique: 'fence_strip',
        originalText: rawInput,
        repairedText: cleaned
      };
    } catch {
      // Continue to syntax clean
    }

    // Stage 3: Syntax normalization (trailing commas, single quotes, unquoted keys)
    cleaned = this.normalizeJsonSyntax(cleaned);
    try {
      const data = JSON.parse(cleaned);
      return {
        success: true,
        data,
        wasRepaired: true,
        repairTechnique: 'syntax_clean',
        originalText: rawInput,
        repairedText: cleaned
      };
    } catch {
      // Continue to bracket balancing
    }

    // Stage 4: Bracket & quote balance repair for truncated outputs
    const balanced = this.balanceTruncatedJson(cleaned);
    try {
      const data = JSON.parse(balanced);
      return {
        success: true,
        data,
        wasRepaired: true,
        repairTechnique: 'bracket_balance',
        originalText: rawInput,
        repairedText: balanced
      };
    } catch (finalErr: any) {
      return {
        success: false,
        wasRepaired: true,
        originalText: rawInput,
        repairedText: balanced,
        error: `JSON parse failed after all repair stages: ${finalErr?.message || String(finalErr)}`
      };
    }
  }

  /**
   * Strips markdown fences like ```json ... ``` or finds the outermost { ... } or [ ... ]
   */
  public static stripMarkdownFences(text: string): string {
    let result = text.trim();

    // Remove leading ```json or ```
    if (result.startsWith('```')) {
      result = result.replace(/^```(?:json|JSON)?\s*\r?\n?/, '');
    }
    // Remove trailing ```
    if (result.endsWith('```')) {
      result = result.replace(/\r?\n?```\s*$/, '');
    }

    result = result.trim();

    // If still surrounded by other prose, slice between first '{' and last '}' or first '[' and last ']'
    const firstBrace = result.indexOf('{');
    const firstBracket = result.indexOf('[');
    let startIdx = -1;

    if (firstBrace !== -1 && (firstBracket === -1 || firstBrace < firstBracket)) {
      startIdx = firstBrace;
      const lastBrace = result.lastIndexOf('}');
      if (lastBrace > startIdx) {
        result = result.substring(startIdx, lastBrace + 1);
      } else {
        result = result.substring(startIdx);
      }
    } else if (firstBracket !== -1) {
      startIdx = firstBracket;
      const lastBracket = result.lastIndexOf(']');
      if (lastBracket > startIdx) {
        result = result.substring(startIdx, lastBracket + 1);
      } else {
        result = result.substring(startIdx);
      }
    }

    return result.trim();
  }

  /**
   * Cleans trailing commas, fixes single quotes, and quotes bare keys.
   */
  public static normalizeJsonSyntax(text: string): string {
    let s = text;

    // Remove comments (single line // and multi line /* */)
    s = s.replace(/\/\/.*$/gm, '');
    s = s.replace(/\/\*[\s\S]*?\*\//g, '');

    // Replace single quotes with double quotes around strings:
    // 'value' -> "value", but beware escaped quotes
    s = s.replace(/'([^'\\]*(?:\\.[^'\\]*)*)'/g, '"$1"');

    // Quote unquoted object keys: { key: "value" } -> { "key": "value" }
    // Look for identifier followed by colon: ([a-zA-Z0-9_$]+)\s*:
    s = s.replace(/([{,]\s*)([a-zA-Z_][a-zA-Z0-9_$]*)\s*:/g, '$1"$2":');

    // Remove trailing commas before closing braces/brackets
    s = s.replace(/,\s*([}\]])/g, '$1');

    return s.trim();
  }

  /**
   * Balances unclosed brackets, braces, and strings from cut-off model responses.
   */
  public static balanceTruncatedJson(text: string): string {
    let s = text.trim();

    // If string ends with an unclosed quote, close it
    let inString = false;
    let escape = false;
    const stack: ('{' | '[')[] = [];

    for (let i = 0; i < s.length; i++) {
      const char = s[i];
      if (escape) {
        escape = false;
        continue;
      }
      if (char === '\\') {
        escape = true;
        continue;
      }
      if (char === '"') {
        inString = !inString;
        continue;
      }
      if (!inString) {
        if (char === '{' || char === '[') {
          stack.push(char);
        } else if (char === '}') {
          if (stack.length > 0 && stack[stack.length - 1] === '{') {
            stack.pop();
          }
        } else if (char === ']') {
          if (stack.length > 0 && stack[stack.length - 1] === '[') {
            stack.pop();
          }
        }
      }
    }

    // If still inside an unclosed string, close the quote
    if (inString) {
      s += '"';
    }

    // Strip trailing comma before closing structures
    s = s.replace(/,\s*$/, '');

    // Close remaining open brackets in reverse order
    while (stack.length > 0) {
      const open = stack.pop();
      if (open === '{') {
        // If it ended with key: add dummy null
        if (/:\s*$/.test(s)) {
          s += 'null';
        }
        s += '}';
      } else if (open === '[') {
        s += ']';
      }
    }

    return s;
  }
}
